  settings_search_idx_capped_roots: 'Laissé de côté :',
  settings_search_idx_near_cap: 'L’index est à {pct} % de sa limite ({max} fichiers) : s’ils continuent d’augmenter, Xenon cessera de les ajouter et la recherche ne les verra pas tous. Retirez un dossier de la liste ci-dessus, ou indiquez des dossiers précis plutôt que des disques entiers.',
  settings_search_idx_fda: 'macOS a révoqué l\'Accès complet au disque de Xenon. Cela arrive à chaque mise à jour, car l\'autorisation est liée à la signature de l\'app. Tant qu\'elle manque, Xenon n\'indexe pas votre dossier utilisateur : sinon macOS demanderait l\'autorisation pour le Bureau, Documents, Téléchargements, Photos et Musique à chaque passage. Réactivez-le dans Réglages Système → Confidentialité et sécurité → Accès complet au disque : retirez Xenon de la liste puis rajoutez-la.',
  disk_fda_title: 'macOS a révoqué une autorisation de Xenon',
  disk_fda_text: 'Après chaque mise à jour, macOS retire à Xenon l\'Accès complet au disque. Sans lui, la carte du disque et la recherche restent vides. Réactivez-le : retirez Xenon de la liste puis rajoutez-la.',
