  settings_bg_code_help_title: 'Comment écrire le code',
  settings_bg_code_help_contract: 'Définissez une fonction draw(ctx, t, w, h) : ctx est le contexte 2D du canvas, t les secondes écoulées, w et h la taille en pixels. Elle est appelée à la fréquence choisie dans « Images par seconde » (30 par défaut, jusqu\'à 60). Déclarez particules ou état avec const/let au-dessus de la fonction pour qu\'ils persistent entre les images.',
  settings_bg_fps: 'Images par seconde',
