  'remote.intro_title': 'Contrôle à distance sécurisé du PC',
  'remote.intro_p1': 'Vous permet d\'accéder au bureau de votre PC depuis un smartphone ou une tablette via votre réseau Tailscale privé (VPN pair à pair). Le flux vidéo est géré par Sunshine ; le client gratuit Moonlight tourne sur votre téléphone.',
