  surface_mode_both_hint: 'Le tableau de bord s’ouvre sur le téléphone appairé et continue de s’ouvrir ici aussi.',
  ra_guide_open: 'Guide pas à pas',
  ra_guide_title: 'Configurer le téléphone, pas à pas',
  ra_guide_close: 'Fermer le guide',
  ra_guide_sub: 'Les étapes 1 à 3 mettent le tableau de bord sur le téléphone à la maison. Le reste ne sert que si vous le voulez aussi en dehors.',
  ra_guide_group_home: 'À la maison, sur votre Wi-Fi',
  ra_guide_group_away: 'En dehors (facultatif)',
  ra_guide_ack: 'C’est fait',
  ra_guide_undo: 'Pas encore',
  ra_guide_s1: 'Activez l’accès depuis les autres appareils',
  ra_guide_s1_body: 'C’est éteint tant que vous ne l’allumez pas. Tant que c’est éteint, Xenon répond à ce PC et à rien d’autre.',
  ra_guide_s2: 'Visez le QR code avec le téléphone',
  ra_guide_s2_body: 'Le code est une invitation, pas un mot de passe : il dure trois minutes et cesse de fonctionner après quelques essais ratés. Le tableau de bord s’ouvre dans le navigateur du téléphone. Il n’y a rien à installer dessus.',
  ra_guide_s2_wait: 'Disponible une fois l’interrupteur ci-dessus activé.',
  ra_guide_s3: 'Ajoutez-le à l’écran d’accueil du téléphone',
  ra_guide_s3_body: 'Sur iPhone, appuyez sur Partager puis sur Sur l’écran d’accueil. Sur Android, Chrome propose de l’installer. Xenon s’ouvre ensuite avec sa propre icône, en plein écran, et le micro et les notifications fonctionnent là.',
  ra_guide_s4: 'Activez l’adresse sécurisée',
  ra_guide_s4_body: 'Cela donne à ce PC un nom bien à lui qui marche depuis n’importe où, sur une connexion chiffrée. Cela passe par Tailscale, qui est gratuit, et Xenon l’installe et s’y connecte pour vous. Vous ne créez aucun compte chez Xenon.',
  ra_guide_s5: 'Activez les certificats HTTPS dans votre compte Tailscale',
  ra_guide_s5_body: 'C’est la seule étape que Xenon ne peut pas faire à votre place. Ouvrez la console d’administration Tailscale, descendez jusqu’à HTTPS Certificates et appuyez sur Enable. C’est gratuit sur toutes les formules. Revenez ensuite ici : Xenon a continué d’attendre.',
  ra_guide_s6: 'Installez Tailscale sur le téléphone, même compte',
  ra_guide_s6_body: 'Prenez-le sur l’App Store ou Google Play, connectez-vous avec le même compte que vous venez d’utiliser, et activez son interrupteur. C’est l’étape que tout le monde oublie. Quand elle manque, le téléphone dit qu’il n’arrive pas du tout à ouvrir l’adresse : rien n’est cassé, cette adresse n’existe qu’à l’intérieur de votre réseau.',
  ra_guide_s7: 'Appairez à nouveau le téléphone sur la nouvelle adresse',
  ra_guide_s7_body: 'Appuyez sur Ajouter un appareil à l’étape 2 et scannez de nouveau. Le navigateur lie un appairage à l’adresse sur laquelle il a été fait : un téléphone appairé sur l’adresse de la maison ne l’est pas sur la sécurisée. Ensuite, seule la nouvelle adresse est nécessaire, chez vous comme ailleurs.',
  ra_guide_done_title: 'La configuration est terminée',
  ra_guide_done_body: 'Le téléphone est appairé. Dernière chose : Xenon doit-il continuer à s’ouvrir sur ce PC aussi ?',
  ra_guide_keep: 'Le garder ici aussi',
  ra_guide_hide: 'Masquer Xenon sur ce PC',
  ra_guide_hide_note: 'Le masquer empêche Xenon de s’ouvrir sur ce PC, y compris à l’ouverture de session. Il continue de tourner en arrière-plan, donc le téléphone fonctionne toujours. Vous ramenez la fenêtre depuis l’icône Xenon à côté de l’horloge, ou depuis Réglages puis Écran.',
  ra_guide_hide_browser: 'Ceci est le tableau de bord dans un navigateur : il n’y a pas de fenêtre à masquer. Dans l’application Xenon, vous pouvez aussi choisir qu’elle ne s’ouvre plus sur ce PC.',
